from collections import OrderedDict


class TTLCache:
    """A bounded LRU cache with expiration measured by an injected clock."""

    def __init__(self, capacity, clock):
        if isinstance(capacity, bool) or not isinstance(capacity, int) or capacity <= 0:
            raise ValueError("capacity must be a positive integer")
        self._capacity = capacity
        self._clock = clock
        self._entries = OrderedDict()

    def put(self, key, value, ttl):
        if ttl <= 0:
            self._entries.pop(key, None)
            return

        now = self._clock()
        expiry = now + ttl
        if key not in self._entries and len(self._entries) >= self._capacity:
            # Expired entries can occur anywhere in the LRU order.
            expired = [
                stored_key
                for stored_key, (_, stored_expiry) in self._entries.items()
                if now >= stored_expiry
            ]
            for stored_key in expired:
                del self._entries[stored_key]
            if len(self._entries) >= self._capacity:
                self._entries.popitem(last=False)

        self._entries[key] = (value, expiry)
        self._entries.move_to_end(key)

    def get(self, key, default=None):
        try:
            value, expiry = self._entries[key]
        except KeyError:
            return default
        if self._clock() >= expiry:
            del self._entries[key]
            return default
        self._entries.move_to_end(key)
        return value

