def dependency_layers(graph):
    """Return sorted runnable layers, raising ValueError for invalid graphs."""
    dependents = {node: [] for node in graph}
    remaining = {}

    for node, dependencies in graph.items():
        prerequisites = set(dependencies)
        for prerequisite in prerequisites:
            if prerequisite not in dependents:
                raise ValueError(f"Unknown dependency {prerequisite!r} for {node!r}")
            if prerequisite == node:
                raise ValueError(f"Self-dependency for {node!r}")
            dependents[prerequisite].append(node)
        remaining[node] = len(prerequisites)

    runnable = sorted(node for node, count in remaining.items() if count == 0)
    layers = []
    processed = 0
    while runnable:
        layers.append(runnable)
        processed += len(runnable)
        next_layer = []
        for node in runnable:
            for dependent in dependents[node]:
                remaining[dependent] -= 1
                if remaining[dependent] == 0:
                    next_layer.append(dependent)
        runnable = sorted(next_layer)

    if processed != len(remaining):
        raise ValueError("Dependency graph contains a cycle")
    return layers

