def dependency_layers(graph):
    """Return sorted layers of nodes whose prerequisites are already complete.

    Each dependency iterable is consumed once. Invalid dependencies and cycles
    raise ValueError; the mapping and dependency containers are not modified.
    """
    remaining = {}
    dependents = {node: [] for node in graph}

    for node, prerequisites in graph.items():
        dependencies = set(prerequisites)
        for dependency in dependencies:
            if dependency not in dependents:
                raise ValueError(f"Unknown dependency {dependency!r} for {node!r}")
            if dependency == node:
                raise ValueError(f"Self-dependency for {node!r}")
            dependents[dependency].append(node)
        remaining[node] = len(dependencies)

    runnable = [node for node, count in remaining.items() if count == 0]
    layers = []
    processed = 0
    while runnable:
        layer = sorted(runnable)
        layers.append(layer)
        processed += len(layer)
        runnable = []
        for node in layer:
            for dependent in dependents[node]:
                remaining[dependent] -= 1
                if remaining[dependent] == 0:
                    runnable.append(dependent)

    if processed != len(remaining):
        raise ValueError("Dependency graph contains a cycle")
    return layers

